CREATE SEQUENCE IF NOT EXISTS shared_seq;

CREATE TABLE "Mixed Case"."Weird Table" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "select" integer,
    "a""b" text,
    x bigint DEFAULT nextval('shared_seq'::regclass),
    "Serial Col" serial,
    CONSTRAINT "Weird Table_select_x_key" UNIQUE ("select", x) DEFERRABLE
);

CREATE UNIQUE INDEX weird_replident ON "Mixed Case"."Weird Table" USING btree ("Id");
ALTER TABLE "Mixed Case"."Weird Table" REPLICA IDENTITY USING INDEX weird_replident;
